import{_ as d,B as o,o as n,c as r,a8 as l,a as t,f as a,E as i}from"./chunks/framework.CNIpabDg.js";const b=JSON.parse('{"title":"Shell reference","description":"Xila shell composition syntax, expansion rules, statuses, resource limits, and built-in command inventory.","frontmatter":{"layout":"doc","docType":"reference","description":"Xila shell composition syntax, expansion rules, statuses, resource limits, and built-in command inventory."},"headers":[],"relativePath":"reference/shell.md","filePath":"reference/shell.md","lastUpdated":1793145952000}'),c={name:"reference/shell.md"};function h(p,e,u,m,g,k){const s=o("CodeReference");return n(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[3]||(e[3]=l(`<h1 id="shell-reference" tabindex="-1">Shell reference <a class="header-anchor" href="#shell-reference" aria-label="Permalink to &quot;Shell reference&quot;">​</a></h1><p>Xila&#39;s command-line shell implements a bounded command language for interactive use and <code>shell -c</code>. It is intentionally smaller than POSIX shell syntax.</p><h2 id="invocation" tabindex="-1">Invocation <a class="header-anchor" href="#invocation" aria-label="Permalink to &quot;Invocation&quot;">​</a></h2><p>Interactive input is parsed one line at a time. When the shell executable receives already-separated arguments, those arguments are preserved literally. Use <code>-c</code> to explicitly parse command source, or <code>-s PATH</code> to execute a line-oriented VFS script:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>shell -c &#39;echo first | wc -l&#39;</span></span>
<span class="line"><span>shell -s /data/startup.xsh</span></span></code></pre></div><p>EOF executes a final unterminated interactive or script line. A script supports LF/CRLF; each line has at most 4096 source bytes. Script commands share that shell invocation&#39;s directory/environment state while reading input from the separate VFS script file. Script command failures continue by default and the final command status is returned. Syntax, read, UTF-8 and overlong-line errors identify the path/line and stop with status 2; <code>exit</code> stops the script. Nested noninteractive shell invocations are limited to four active levels.</p><h2 id="composition-operators" tabindex="-1">Composition operators <a class="header-anchor" href="#composition-operators" aria-label="Permalink to &quot;Composition operators&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;hello world&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$NAME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> first</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /temporary/example</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> second</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /temporary/example</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /temporary/example</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">missing-command</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /temporary/errors</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recovered</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">long-running-command</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /temporary/result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> foreground</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Syntax</th><th>Behavior</th></tr></thead><tbody><tr><td><code>A | B</code></td><td>Run pipeline stages concurrently; the pipeline status is B&#39;s status.</td></tr><tr><td><code>A &amp;&amp; B</code></td><td>Run B only when A succeeds.</td></tr><tr><td><code>A || B</code></td><td>Run B only when A fails.</td></tr><tr><td><code>A ; B</code></td><td>Run sequential command lists.</td></tr><tr><td><code>A &amp;</code></td><td>Start the preceding conditional list in a background task.</td></tr><tr><td><code>&lt; FILE</code></td><td>Read standard input from FILE.</td></tr><tr><td><code>&gt; FILE</code></td><td>Create/truncate FILE for standard output.</td></tr><tr><td><code>&gt;&gt; FILE</code></td><td>Append standard output to FILE.</td></tr><tr><td><code>2&gt; FILE</code></td><td>Create/truncate FILE for standard error.</td></tr><tr><td><code>2&gt;&gt; FILE</code></td><td>Append standard error to FILE.</td></tr></tbody></table><p><code>|</code> binds more tightly than <code>&amp;&amp;</code> and <code>||</code>. The two conditional operators have equal precedence and evaluate left to right. Redirections belong to one command, are applied left to right, and override a pipeline endpoint when they target the same stream.</p><p>Background input is <code>/devices/standard_io/null</code>. Output and error inherit the shell&#39;s streams unless redirected and may interleave with foreground output. The shell supports up to eight active background lists; job listing, cancellation, and foreground/background switching are not implemented.</p><h2 id="quoting-and-expansion" tabindex="-1">Quoting and expansion <a class="header-anchor" href="#quoting-and-expansion" aria-label="Permalink to &quot;Quoting and expansion&quot;">​</a></h2><ul><li>Single quotes preserve contents literally.</li><li>Double quotes allow variable expansion.</li><li>Outside single quotes, backslash protects the following character.</li><li>Inside double quotes, backslash protects <code>$</code>, <code>&quot;</code>, and <code>\\</code>.</li><li><code>#</code> at a word boundary begins a comment.</li><li><code>$NAME</code>, <code>\${NAME}</code>, and <code>$?</code> expand while a command is prepared.</li><li>Variable names use ASCII letters, digits, and underscores, with a letter or underscore first.</li><li>Missing variables expand to an empty string.</li></ul><p>Expansion does not split a variable value on whitespace and does not reinterpret the value as shell operators. Quoted and unquoted fragments may form one argument.</p><h2 id="exit-statuses" tabindex="-1">Exit statuses <a class="header-anchor" href="#exit-statuses" aria-label="Permalink to &quot;Exit statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>Status</th></tr></thead><tbody><tr><td>Success</td><td>0</td></tr><tr><td>General built-in failure</td><td>1</td></tr><tr><td><code>false</code></td><td>1</td></tr><tr><td>Malformed <code>shell -c</code> source</td><td>2</td></tr><tr><td>Unknown command</td><td>127</td></tr><tr><td>External executable</td><td>Preserved within 0–255</td></tr><tr><td>Pipeline</td><td>Status of the last stage</td></tr><tr><td>Successful background-list launch</td><td>Sets <code>$?</code> to 0</td></tr></tbody></table><p><code>$?</code> contains the preceding foreground status.</p><h2 id="resource-limits" tabindex="-1">Resource limits <a class="header-anchor" href="#resource-limits" aria-label="Permalink to &quot;Resource limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th style="text-align:right;">Limit</th></tr></thead><tbody><tr><td>Source line</td><td style="text-align:right;">4096 bytes</td></tr><tr><td>Script buffer</td><td style="text-align:right;">4097 bytes</td></tr><tr><td>Tokens per line</td><td style="text-align:right;">256</td></tr><tr><td>Commands per line</td><td style="text-align:right;">32</td></tr><tr><td>Stages per pipeline</td><td style="text-align:right;">8</td></tr><tr><td>Expanded arguments and redirection paths per command</td><td style="text-align:right;">8192 bytes</td></tr><tr><td>Buffered formatted output per built-in</td><td style="text-align:right;">8192 bytes</td></tr><tr><td>Buffered bytes per pipe</td><td style="text-align:right;">512</td></tr><tr><td>Active background lists per shell</td><td style="text-align:right;">8</td></tr></tbody></table><p>These limits bound shell-owned parsing and pipe storage. They do not bound allocations made by launched commands, inherited environment data, the WASM runtime, or task infrastructure.</p><h2 id="built-in-commands" tabindex="-1">Built-in commands <a class="header-anchor" href="#built-in-commands" aria-label="Permalink to &quot;Built-in commands&quot;">​</a></h2><p><code>help</code> lists registered built-ins and executable entries found in the task&#39;s <code>Paths</code> locations. <code>help COMMAND</code> prints usage for a built-in without launching it.</p><p>The current built-in registry contains:</p><table tabindex="0"><thead><tr><th>Area</th><th>Commands</th></tr></thead><tbody><tr><td>Shell/state</td><td><code>true</code>, <code>false</code>, <code>exit</code>, <code>cd</code>, <code>pwd</code>, <code>clear</code>, <code>help</code></td></tr><tr><td>Environment</td><td><code>export</code>, <code>unset</code>, <code>printenv</code>, <code>which</code></td></tr><tr><td>Files/directories</td><td><code>ls</code>, <code>cat</code>, <code>stat</code>, <code>mkdir</code>, <code>rm</code>, <code>rmdir</code>, <code>realpath</code>, <code>touch</code>, <code>mv</code>, <code>cp</code>, <code>find</code></td></tr><tr><td>Text/streams</td><td><code>echo</code>, <code>grep</code>, <code>wc</code>, <code>head</code>, <code>tail</code>, <code>tree</code></td></tr><tr><td>Timing</td><td><code>sleep</code></td></tr><tr><td>Permissions</td><td><code>chmod</code></td></tr><tr><td>Network</td><td><code>web_request</code>, <code>dns_resolve</code>, <code>ping</code>, <code>ip</code></td></tr></tbody></table><p>Selected recent utilities:</p><ul><li><code>grep PATTERN [FILE]...</code> performs literal substring matching and reads standard input when no file is supplied or a file operand is <code>-</code>.</li><li><code>touch FILE...</code> creates missing files and updates access and modification times.</li><li><code>realpath PATH...</code> prints canonical absolute paths for existing files/directories.</li><li><code>sleep DURATION</code> accepts a nonnegative integer followed by <code>ms</code>, <code>s</code>, <code>m</code>, or <code>h</code>; no suffix means seconds.</li><li><code>chmod MODE PATH</code> accepts octal permissions from <code>000</code> through <code>777</code>, optionally with a leading zero.</li><li><code>tree [-L N] [PATH]</code> streams a hierarchy without collecting sibling entries; depth is bounded to 32.</li><li><code>mv SOURCE DESTINATION</code> renames within one mounted filesystem and uses the exact destination path.</li><li><code>cp SOURCE DESTINATION</code> streams a regular file into a newly created or truncated destination with a fixed 512-byte buffer. If the destination is an existing directory, the source filename is appended. It does not copy directory trees and rejects directory sources and copies onto the same path.</li><li><code>find [PATH] [-n NAME|--name NAME] [-t TYPE|--type TYPE] [-d N|--max-depth N]</code> streams matching paths, starting at <code>PATH</code> or the current directory. Name matching is exact; supported types are <code>f</code> (file), <code>d</code> (directory), <code>c</code> (character device), <code>b</code> (block device), <code>p</code> (pipe), <code>s</code> (socket) and <code>l</code> (symlink). It includes a matching start path and hidden entries, with at most 32 levels and 1024-byte paths. Permission, missing-path and traversal errors stop the command.</li></ul><p>Use <code>help COMMAND</code> for the authoritative option syntax of built-ins not detailed here.</p><h2 id="unsupported-shell-syntax" tabindex="-1">Unsupported shell syntax <a class="header-anchor" href="#unsupported-shell-syntax" aria-label="Permalink to &quot;Unsupported shell syntax&quot;">​</a></h2><p>The current language supports line-oriented VFS scripts but not multiline grammar, command substitution, globbing, subshells, descriptor duplication such as <code>2&gt;&amp;1</code>, here-documents, or shell assignment syntax. Newline characters inside explicit command source are whitespace; use <code>;</code> to separate commands.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2>`,30)),t("ul",null,[e[2]||(e[2]=t("li",null,[t("a",{href:"/explanation/architecture/executables/command_line_shell.html"},"Command-line shell architecture"),a(".")],-1)),t("li",null,[i(s,{repo:"applications",path:"executables/shell/command_line/README.md"}),e[0]||(e[0]=a(".",-1))]),t("li",null,[i(s,{repo:"applications",path:"executables/shell/command_line/src/commands/mod.rs"}),e[1]||(e[1]=a(".",-1))])])])}const f=d(c,[["render",h]]);export{b as __pageData,f as default};
